  ('siteTeam', $floreon$[{"name":"YourName","role":"Owner","row":1},{"name":"DevName","role":"Developer","row":1},{"name":"AdminName","role":"Admin","row":2},{"name":"Mod1","role":"Moderator","row":2},{"name":"Mod2","role":"Moderator","row":2},{"name":"Helper1","role":"Helper","row":3},{"name":"Helper2","role":"Helper","row":3},{"name":"Helper3","role":"Helper","row":3},{"name":"Trial1","role":"Trial Helper","row":4},{"name":"Trial2","role":"Trial Helper","row":4},{"name":"Trial3","role":"Trial Helper","row":4},{"name":"Trial4","role":"Trial Helper","row":4},{"name":"EventsName","role":"Events Manager","row":5}]$floreon$::jsonb),
  ('sitePlans', $floreon$[{"id":"dahlia","name":"Dahlia","price":200,"perks":["Dahlia chat prefix","3 player homes","Starter kit every week","Access to the Dahlia lounge"]},{"id":"hibiscus","name":"Hibiscus","price":400,"perks":["Everything in Dahlia","6 player homes","Colored name in chat","Particle trail & pet cosmetic"]},{"id":"sakura","name":"Sakura","price":800,"perks":["Everything in Hibiscus","10 player homes","Priority join when server is full","Exclusive Sakura cosmetics & kit"]}]$floreon$::jsonb),
