biomes":["Lush","Forest"],"blocks":[],"kind":"paradox"},{"name":"Nihilego","cond":[],"biomes":["End"],"blocks":[],"kind":"ultra"},{"name":"Buzzwole","cond":["Can see the sky"],"biomes":["Swamp"],"blocks":[],"kind":"ultra"},{"name":"Pheromosa","cond":["Can see the sky"],"biomes":["Desert","End"],"blocks":[],"kind":"ultra"},{"name":"Xurkitree","cond":[],"biomes":["Swamp","End"],"blocks":[],"kind":"ultra"},{"name":"Celesteela","cond":["Can see the sky"],"biomes":["Bamboo","End"],"blocks":[],"kind":"ultra"},{"name":"Guzzlord","cond":[],"biomes":["End"],"blocks":[],"kind":"ultra"},{"name":"Kartana","cond":["Can see the sky"],"biomes":["Bamboo"],"blocks":[],"kind":"ultra"},{"name":"Poipole","cond":[],"biomes":["End"],"blocks":["Purpur Block"],"kind":"ultra"},{"name":"Stakataka","cond":["Can see the sky"],"biomes":["Peak","End"],"blocks":[],"kind":"ultra"},{"name":"Blacephalon","cond":[],"biomes":["Spooky"],"blocks":[],"kind":"ultra"}]$floreon$::jsonb),
  ('czLegendaries', $floreon$[{"name":"Articuno","structure":true,"paras":["To obtain Articuno you need to craft a <strong>\"Urn of Frost\"</strong> and defeat <strong>50 ice-type Pokémon</strong>, either by using melee or through Pokémon battle, while you have the urn in your inventory. (You can't fill multiple urns at the same time.)","Once the urn is filled, all you need to do is right-click with it in your hand and a <strong>level 40 Articuno</strong> will spawn, with a 2% chance of it being shiny.","You will also receive an <strong>\"Arctic Stone\"</strong> upon using the filled urn. You can put it together with the other 2 bird stones to craft the <strong>\"Vortex Stone\"</strong> to obtain Lugia. To obtain the Galarian form, simply use a <strong>\"Galarian Urn\"</strong> instead."],"cond":[],"biomes":[],"blocks":[],"images":[]},{"name":"Groudon","cond":[],"biomes":["Volcanic","Desert","Arid","Thermal","Badlands"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Kyogre","cond":["Rainy weather"],"biomes":["Deep Ocean","Ocean","Frozen Ocean"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Rayquaza","cond":["Daylight","Not raining"],"biomes":["Sky","End","Highlands"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Jirachi","cond":[],"biomes":["Magical","Mirage Island","Mushroom"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Deoxys","cond":[],"biomes":["End"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Manaphy","cond":[],"biomes":["Ocean","Deep Ocean"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Shaymin","cond":["Can see the sky","Night time","Not raining"],"biomes":["Floral","Highlands"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Tornadus","cond":["Rainy weather"],"biomes":["Jungle","Bamboo"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Landorus","cond":["Not raining"],"biomes":["Floral","Savanna","Desert"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Thundurus","cond":["Thunderstorm weather"],"biomes":["Plains","Mountain","Badlands"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Genesect","cond":[],"biomes":["End"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Meloetta","cond":[],"biomes":["Floral"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Xerneas","cond":["Daytime"],"biomes":["Forest","Magical","Floral"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Yveltal","cond":["Night time"],"biomes":["Swamp","Spooky"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Zygarde","cond":["Min. sky light is 0","Max sky light is 7","Max Y=0 to -48"],"biomes":["Forest","Cave","Swamp","Deep Dark"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Diancie","cond":["Min. sky light is 0","Max. sky light is 7","Max Y = 0","No sky"],"biomes":["Cave","Lush","Overworld"],"blocks":["Amethyst Block","Amethyst Cluster","Budding Amethyst","Large Amethyst Bud","Medium Amethyst Bud","Small Amethyst Bud"],"structure":false,"paras":[],"images":[]},{"name":"Volcanion","cond":["Daytime","Can see the sky"],"biomes":["Nether","Volcanic"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Type: Null","cond":[],"biomes":["Deep Dark","End"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Tapu Koko","cond":["Min. sky light is 8","Max. sky light is 15"],"biomes":["Jungle","Tropical Island","Beach"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Tapu Lele","cond":[],"biomes":["Jungle","Tropical Island","Beach"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Tapu Bulu","cond":[],"biomes":["Jungle","Tropical Island","Beach"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Tapu Fini","cond":[],"biomes":["Jungle","Tropical Island","Beach"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Necrozma","cond":[],"biomes":["Deep Dark","End"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Magearna","cond":[],"biomes":["Deep Dark","End"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Marshadow","cond":["No sky"],"biomes":["Swamp"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Zeraora","cond":["Can see the sky"],"biomes":["Savanna"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Kubfu","cond":[],"biomes":["Jungle","Bamboo"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Zarude","cond":[],"biomes":["Jungle"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Glastrier","cond":[],"biomes":["Snowy Forest","Taiga","Mountain"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Spectrier","cond":[],"biomes":["Forest","Spooky","Plains"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Calyrex","cond":[],"biomes":["Has Season/Autumn","Floral"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Enamorus","cond":[],"biomes":["Floral","Swamp"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Koraidon","cond":[],"biomes":["Badlands","Savanna","Plateau","Mountain"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Miraidon","cond":[],"biomes":["Deep Dark"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Okidogi","cond":["Can see the sky"],"biomes":["Savanna"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Munkidori","cond":["Can see the sky"],"biomes":["Jungle"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Ogerpon","cond":[],"biomes":["Floral","Bamboo","Jungle"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Fezandipiti","cond":["Can see the sky"],"biomes":["Peak"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Pecharunt","cond":["Can see the sky"],"biomes":["Swamp","Spooky"],"blocks":[],"structure":false,"paras":[],"images":[]},{"name":"Terapagos","cond":["Min. sky light is 0","Max. sky light is 7","Max Y = 0 to -32"],"biomes":["Mountain","Magical","River","Jungle","Cave"],"blocks":[],"structure":false,"paras":[],"images":[]}]$floreon$::jsonb)
