-- legendaries get an "images" list for the new picture uploads
update public.content
   set data = (select jsonb_agg(case when e ? 'images' then e else e || '{"images":[]}'::jsonb end) from jsonb_array_elements(data) e)
 where key = 'czLegendaries' and exists (select 1 from jsonb_array_elements(data) e where not e ? 'images');

-- ---------- pages ----------
-- Sections edited in the old admin panel (FAQs, features, rules, votes, series, About)
-- are taken from the content table; otherwise the starting content is used.
do $do$
declare
  t text := $floreon$[{"slug":"home","title":"Home","published":true,"description":"Floreon is a cozy, whitelist-only Minecraft community. Play Cozymon, our Cobblemon survival server.","blocks":[{"id":"b001","type":"hero","size":"large","logo":true,"title":"","subtitle":"A cozy Minecraft community for building, exploring, and making friends.","images":[],"petals":true},{"id":"b002","type":"heading","eyebrow":"","title":"Latest news","lead":"Announcements, events and updates from the team.","align":"left"},{"id":"b003","type":"news","limit":3},{"id":"b004","type":"heading","eyebrow":"","title":"About Floreon","lead":"We're a small, friendly community that cares more about good vibes than grinding. Build something you love, join a game night, or just hang out with the regulars. Everyone is welcome here, whether you've played for ten years or ten minutes.","align":"left"},{"id":"b005","type":"heading","eyebrow":"","title":"Pick a gamemode","lead":"Floreon has more than one world to explore.","align":"left"},{"id":"b006","type":"cards","style":"links","search":false,"items":[{"name":"Cozymon","text":"Our Cobblemon survival server. Catch, train, and battle Pokémon while you build.","chips":[],"url":"/cozymon","color":"sakura"}]},{"id":"b007","type":"heading","eyebrow":"","title":"How to get whitelisted","lead":"Floreon is whitelist-only. Follow these steps to get in.","align":"left","anchor":"whitelist"},{"id":"b008","type":"steps","items":[{"title":"Apply in Discord","text":"Join our Discord server and fill up the whitelist form. Double-check your Minecraft username and answers, because accuracy matters."},{"title":"Wait for approval","text":"The team reviews every application. You'll hear back in Discord once you're accepted."},{"title":"Install the modpack","text":"Once accepted, you'll get the modpack in our Discord. Install it, launch the game and join. Floreon is already in its server list."}]},{"id":"b009","type":"buttons","align":"left","items":[{"label":"Join Discord and apply","url":"","style":"primary","discord":true}]},{"id":"b00a","type":"heading","eyebrow":"","title":"Meet the team","lead":"The people who keep the server running and the community kind.","align":"left"},{"id":"b00b","type":"team"}],"sort":0},{"slug":"cozymon","title":"About Cozymon","published":true,"description":"Cozymon is Floreon's Cobblemon survival server: level caps, legendaries, a casino, a player economy and events.","blocks":[{"id":"b00c","type":"hero","size":"small","logo":false,"title":"","subtitle":"","images":[],"petals":true},{"id":"b00d","type":"heading","eyebrow":"Cozymon","title":"About Cozymon","lead":"@@czAboutLead","align":"left"},{"id":"b00e","type":"text","card":true,"html":"@@czAboutHtml"},{"id":"b00f","type":"buttons","align":"left","items":[{"label":"How to get whitelisted","url":"/#whitelist","style":"primary","discord":false}]}],"sort":1},{"slug":"cozymon/features","title":"Cozymon Features","published":true,"description":"Every mod in the Cozymon Cobblemon modpack.","blocks":[{"id":"b00g","type":"heading","eyebrow":"Cozymon","title":"Features & mod list","lead":"Cozymon runs a Cobblemon modpack. Here is what's inside.","align":"left"},{"id":"b00h","type":"cards","style":"flowers","search":true,"items":"@@czFeatures"}],"sort":2},{"slug":"cozymon/faq","title":"Cozymon FAQs","published":true,"description":"Answers to common Cozymon questions, plus the trainer series guide.","blocks":[{"id":"b00i","type":"heading","eyebrow":"Cozymon","title":"FAQs","lead":"Quick answers to the most common Cozymon questions.","align":"left"},{"id":"b00j","type":"faq","search":true,"items":"@@czFaqs"},{"id":"b00k","type":"heading","eyebrow":"","title":"Series guide","lead":"Defeat these trainers to raise your level cap. Each trainer has a signature item.","align":"left"},{"id":"b00l","type":"tables","columns":["Trainer name","Signature item"],"tables":"@@czSeries"}],"sort":3},{"slug":"cozymon/spawns","title":"Cozymon Spawns","published":true,"description":"Where to find Paradox Pokémon and Ultra Beasts on Cozymon.","blocks":[{"id":"b00m","type":"heading","eyebrow":"Cozymon","title":"Spawns","lead":"Search for a Pokémon, or filter by the biome it spawns in. Meet the requirements on each card for a chance to find it.","align":"left"},{"id":"b00n","type":"spawns"}],"sort":4},{"slug":"cozymon/legendaries","title":"Cozymon Legendaries","published":true,"description":"How to get every legendary Pokémon on Cozymon.","blocks":[{"id":"b00o","type":"heading","eyebrow":"Cozymon","title":"Legendaries","lead":"Pick a legendary below to see how to get it. Some have a structure or item to summon them manually, the rest can only spawn when you meet their spawn requirements.","align":"left"},{"id":"b00p","type":"legendaries"}],"sort":5},{"slug":"rules","title":"Rules","published":true,"description":"Floreon server rules.","blocks":[{"id":"b00q","type":"heading","eyebrow":"","title":"Server rules","lead":"A few simple rules keep Floreon cozy for everyone. Breaking them can lead to a mute, kick, or ban.","align":"left"},{"id":"b00r","type":"rules","items":"@@siteRules"}],"sort":6},{"slug":"vote","title":"Vote","published":true,"description":"Vote for Floreon and earn in-game rewards.","blocks":[{"id":"b00s","type":"heading","eyebrow":"","title":"Vote for Floreon","lead":"Voting helps new players find the server. Vote on each site below to get a reward.","align":"left"},{"id":"b00t","type":"votes","items":"@@siteVotes"}],"sort":7},{"slug":"store","title":"Store","published":true,"description":"Support Floreon with a permanent rank.","blocks":[{"id":"b00u","type":"store","title":"Choose your rank","lead":"Ranks are permanent, one-time purchases. Pay once and keep your rank forever. They support the server and unlock cosmetic and convenience perks.","note":"Ranks are permanent. There are no renewals or subscriptions."}],"sort":8},{"slug":"oneblock","title":"About Oneblock","published":false,"description":"Oneblock: start with a single block and grow your own island.","blocks":[{"id":"b00v","type":"hero","size":"small","logo":false,"title":"","subtitle":"","images":[],"petals":true},{"id":"b00w","type":"heading","eyebrow":"Oneblock","title":"About Oneblock","lead":"@@obAboutLead","align":"left"},{"id":"b00x","type":"text","card":true,"html":"@@obAboutHtml"}],"sort":9},{"slug":"oneblock/features","title":"Oneblock Features","published":false,"description":"","blocks":[{"id":"b00y","type":"heading","eyebrow":"Oneblock","title":"Features","lead":"What makes our Oneblock special.","align":"left"},{"id":"b00z","type":"cards","style":"flowers","search":true,"items":"@@obFeatures"}],"sort":10},{"slug":"oneblock/faq","title":"Oneblock FAQs","published":false,"description":"","blocks":[{"id":"b010","type":"heading","eyebrow":"Oneblock","title":"FAQs","lead":"Quick answers to the most common Oneblock questions.","align":"left"},{"id":"b011","type":"faq","search":true,"items":"@@obFaqs"}],"sort":11}]$floreon$;
begin
  t := replace(t, '"@@czFeatures"', coalesce((select data::text from public.content where key = 'czFeatures'), $floreon$[{"name":"Simple Voice Chat","text":"Talk to nearby players with proximity voice chat."},{"name":"Dream Display","text":"Create in-game screens to stream your favorite videos in Minecraft."},{"name":"Cobblemon","text":"Catch, train, and battle Pokémon in Minecraft."},{"name":"Battle Tower","text":"Cobblemon add-on: a tower of battles to test your team."},{"name":"Cobblemon Booster Packs","text":"Cobblemon add-on with booster packs to open."},{"name":"Global Trading System","text":"Trade Pokémon with other players on the server."},{"name":"Trowel","text":"A very small QoL mod to make placing random blocks less tedious."},{"name":"Dynamax","text":"Cobblemon add-on: Dynamax battles."},{"name":"Mega Evolution","text":"Cobblemon add-on: Mega Evolution in battle."},{"name":"Photography","text":"Take pictures in game using a functional camera."},{"name":"Delight mods","text":"Cooking and farming add-ons with lots of new food.","chips":["Farmer's","Flora","End","Ube","Vegan"]},{"name":"Yuushya Townscape","text":"A powerful Minecraft mod and resource pack combination designed to help players build detailed, realistic, and lively towns, cozy houses, and intricate streetscapes."},{"name":"Waystone","text":"Fast travel between waystones."},{"name":"Lootr","text":"Every player gets their own loot from chests."},{"name":"Emotecraft","text":"Play custom emotes and animations."},{"name":"Kaleidoscope","text":"Adds immersive cooking and tavern experience systems."},{"name":"Macaw's Furniture","text":"Furniture for decorating your home."},{"name":"Sophisticated Backpack","text":"Upgradeable backpacks for extra storage."},{"name":"Grave","text":"A death chest. When you die, your items are stored in a grave so you can go back and get them."},{"name":"And more!","text":"We add new mods over time. Check Discord for updates."}]$floreon$));
  t := replace(t, '"@@obFeatures"', coalesce((select data::text from public.content where key = 'obFeatures'), $floreon$[{"name":"Phases","text":"Break the block to move through phases with new blocks, mobs, and loot."},{"name":"Island Teams","text":"Invite friends to build and grow your island together."},{"name":"Island Upgrades","text":"Expand your border and unlock perks as you progress."},{"name":"Oneblock Shop","text":"Buy and sell resources to speed up your island."},{"name":"Events","text":"Seasonal events and community challenges with prizes."},{"name":"And more!","text":"We'll keep adding to this list. Check Discord for updates."}]$floreon$));
  t := replace(t, '"@@czFaqs"', coalesce((select jsonb_agg(jsonb_build_object('q', e->>'q', 'a', regexp_replace(e->>'a', '\s*<div class="ph">.*?</div></div>', '', 'g')))::text from public.content c, jsonb_array_elements(c.data) e where c.key = 'czFaqs'), $floreon$[{"q":"How to locate Trainers?","a":"\n    <p>You can locate trainers by exploring the world. You will see a small arrow in your Trainer Card when you hold it.</p>\n    <p>You can also spawn trainers using their signature item, which you can find in your Trainer Card. Explore the world and wait for them to spawn around you, or spawn them with a Trainer Spawner and their signature item.</p>"},{"q":"How to fix my Resource Pack?","a":"\n    <p>If your game crashed and you only see a substitute dummy (a brown stuffed toy), it means all your resource packs got disabled. Just put them back in the order below so the server textures don't bug out.</p>\n    "},{"q":"How to progress?","a":"\n    <p>To increase your Pokémon's level cap, you should defeat trainers in your series. Don't have a series yet? Go to <code>/warp tp Series</code> to exchange your Trainer Card for a series. Pick between Brilliant Diamond or Radical Red. The series guide at the bottom of this page lists every trainer.</p>"},{"q":"How to earn Money?","a":"\n    <p>Just like in the regular games, the money on the server is called Pokémon Dollars (or PokéDollars). Here's how you can make some cash in Floreon:</p>\n    <ul>\n      <li>Sell items to the CobbleMerchant</li>\n      <li>Beat trainers in battles</li>\n      <li>Find them in crates</li>\n      <li>Win at the Casino (<code>/warp tp Casino</code>)</li>\n      <li>Send your Pokémon on an expedition</li>\n    </ul>"},{"q":"How to sell items?","a":"\n    <p>You can sell items to any CobbleMerchant on the server. There's one over at <code>/warp tp Shop</code>, or you can make your own by putting a Display Case near a Villager to give them the job.</p>\n    <p>To sell your stuff, just click on a CobbleMerchant and hit the Bank button under your inventory. This switches the menu over to the selling screen, where you can drop in whatever you want to sell!</p>"},{"q":"How to create a Claim?","a":"\n    <p>To claim land, you'll need a Golden Hoe. If you ever want to check who owns a specific spot, just right-click the area with a stick. You'll also get more claim blocks automatically just by playing and staying online!</p>"},{"q":"How do I add someone to a claim?","a":"\n    <p>To give a friend permission in your claim, type <code>/flan menu</code>, click \"Edit permission group,\" and left-click the paper that says \"Trusted.\" After that, click the Anvil and type in their player name.</p>"},{"q":"How to create a Chest Shop?","a":"\n    <p>You can create a chest shop by right-clicking a chest with a paper.</p>\n    <ul>\n      <li>The shop type is from a customer's perspective! BUY means your customers can buy from your shop, SELL means your customers can sell their items to your shop.</li>\n      <li>For a SELL shop, you must allocate a budget so as to not drain your entire balance. You must already have the amount to deposit when creating the shop.</li>\n      <li>Destroying the sign or chest will remove the shop. Any sell budget will be added to your claimable balance in <code>/chestshop</code>.</li>\n      <li>Use <code>/chestshop</code> to check all your shop locations, claim your sales, and see your remaining budget.</li>\n      <li>You must have Flan <code>open container</code> permission in the area to create a shop.</li>\n    </ul>"}]$floreon$));
  t := replace(t, '"@@obFaqs"', coalesce((select jsonb_agg(jsonb_build_object('q', e->>'q', 'a', regexp_replace(e->>'a', '\s*<div class="ph">.*?</div></div>', '', 'g')))::text from public.content c, jsonb_array_elements(c.data) e where c.key = 'obFaqs'), $floreon$[{"q":"How do I start my island?","a":"<p>Join the server and use <code>/ob create</code> (replace with your real command). Your island will be generated with your first block.</p>"},{"q":"How do I invite a friend?","a":"<p>Use <code>/ob invite name</code> (replace with your real command) and ask them to accept.</p>"},{"q":"How do I move to the next phase?","a":"<p>Keep breaking the block. Phases change after a set number of blocks. Check your island menu to see your progress.</p>"}]$floreon$));
  t := replace(t, '"@@czSeries"', coalesce((select data::text from public.content where key = 'czSeries'), $floreon$[{"name":"Brilliant Diamond / Shining Pearl","rows":[["Gym Leader Roark","Smooth Rock"],["Commander Mars","Wide Lens"],["Commander Jupiter","Scope Lens"],["Gym Leader Gardenia","Sunflower"],["Pokemon Trainer Cedric","Everstone"],["Gym Leader Maylene","Black Belt"],["Gym Leader Wake","Nautilus Shell"],["Pokemon Trainer Cedric","Eviolite"],["Gym Leader Fantina","Ender Eye"],["Pokemon Trainer Cedric","Dawn Stone"],["Gym Leader Byron","Metal Coat"],["Commander Saturn","Zoom Lens"],["Commander Mars","Fire Charge"],["Gym Leader Candice","Ice Stone"],["Team Galactic Boss Cyrus","Clock"],["Commander Saturn","Wind Charge"],["Commander Mars &amp; Jupiter","Smoke Ball"],["Team Galactic Boss Cyrus","Echo Shard"],["Gym Leader Volkner","Thunder Stone"],["Pokemon Trainer Cedric","Shiny Stone"],["Elite Four Aaron","Silver Powder"],["Elite Four Bertha","Soft Sand"],["Elite Four Flint","Fire Stone"],["Elite Four Lucian","Psychic Seed"],["Champion Cy","Prism Scale"]]},{"name":"Radical Red","rows":[["Leader Brock","Hard Stone"],["Rocket Admin Archer","Black Tumblestone"],["Rival Terry","Gold Nugget"],["Leader Misty","Mystic Water"],["Trainer Brendan","Silk Scarf"],["Leader Lt. Surge","Magnet"],["Leader Erika","Miracle Seed"],["Boss Giovanni","Upgrade"],["Rival Terry","Soothe Bell"],["Rocket Admin Archer &amp; Diana","Black Sludge"],["Boss Giovanni","Dubious Disc"],["Leader Sabrina","Twisted Spoon"],["Trainer Brendan","Expert Belt"],["Leader Koga","Poison Barb"],["Trainer May","Vivichoke"],["Leader Blaine","Charcoal Stick"],["Rocket Admin Archer","Covert Cloak"],["Rocket Admin Ariana","Utility Umbrella"],["Boss Giovanni","Destiny Knot"],["Leader Clair","Dragon Scale"],["Rival Terry","Lucky Egg"],["Trainer Brendan","Choice Scarf"],["Elite Four Agatha","Cleanse Tag"],["Elite Four Bruno","Focus Band"],["Elite Four Lance","Dragon Fang"],["Elite Four Lorelei","Never Melt Ice"],["Champion Terry","Life Orb"]]}]$floreon$));
  t := replace(t, '"@@siteRules"', coalesce((select data::text from public.content where key = 'siteRules'), $floreon$[{"title":"Be kind and respectful","text":"Treat everyone nicely. No harassment, hate, or toxic behavior."},{"title":"No griefing or stealing","text":"Don't break, steal, or damage other players' builds and items."},{"title":"No cheating","text":"Hacked clients, x-ray, and duping exploits are not allowed."},{"title":"Keep chat friendly","text":"No spam, advertising, or inappropriate content in game or Discord."},{"title":"One account per player","text":"Play on the Minecraft account you applied with. Alt accounts are not allowed."},{"title":"Listen to the team","text":"Follow staff instructions. If you disagree, talk to us in Discord."}]$floreon$));
  t := replace(t, '"@@siteVotes"', coalesce((select data::text from public.content where key = 'siteVotes'), $floreon$[{"name":"Vote site 1","reward":"Vote to earn an in-game reward.","url":"#"},{"name":"Vote site 2","reward":"Vote to earn an in-game reward.","url":"#"},{"name":"Vote site 3","reward":"Vote to earn an in-game reward.","url":"#"},{"name":"Vote site 4","reward":"Vote to earn an in-game reward.","url":"#"},{"name":"Vote site 5","reward":"Vote to earn an in-game reward.","url":"#"}]$floreon$));
  t := replace(t, '"@@czAboutLead"', to_jsonb(coalesce((select data->>'lead' from public.content where key = 'czAbout'), $floreon$Our Cobblemon survival server. Catch, train, and battle Pokémon while you build your dream home.$floreon$))::text);
  t := replace(t, '"@@czAboutHtml"', to_jsonb(coalesce((select string_agg('<p>' || e || '</p>', '') from public.content c, jsonb_array_elements_text(c.data->'about') e where c.key = 'czAbout'), $floreon$<p>Cozymon is a <strong>Cobblemon</strong> server built around a relaxed pace. There's a level cap that rises as you beat trainers, legendaries you can hunt, a casino, a player economy, and plenty of events.</p><p>New here? Head to the home page to see how to get whitelisted, then check the <strong>Features</strong> and <strong>FAQs</strong> pages to get started.</p>$floreon$))::text);
  t := replace(t, '"@@obAboutLead"', to_jsonb(coalesce((select data->>'lead' from public.content where key = 'obAbout'), $floreon$Start with a single block floating in the void and grow your own island, one break at a time.$floreon$))::text);
  t := replace(t, '"@@obAboutHtml"', to_jsonb(coalesce((select string_agg('<p>' || e || '</p>', '') from public.content c, jsonb_array_elements_text(c.data->'about') e where c.key = 'obAbout'), $floreon$<p>Oneblock is our <strong>skyblock-style</strong> gamemode. You begin with one block that keeps giving: ores, mobs, chests, and new phases as you progress.</p><p>Team up with friends on a shared island, and climb the phases. <strong>(Replace this text with your own description.)</strong></p>$floreon$))::text);

  insert into public.pages (slug, title, description, published, blocks, sort)
  select p->>'slug', p->>'title', p->>'description', (p->>'published')::boolean, p->'blocks', (p->>'sort')::int
    from jsonb_array_elements(t::jsonb) p
  on conflict (slug) do nothing;
end
$do$;

-- Check: you should see 12 pages.
select slug, title, published from public.pages order by sort;
